"""Routes for Database, generated by Dryv; the engine implements ExploreDatabaseService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable
from typing import Annotated

from fastapi import APIRouter, Depends, Path, Query, Request

from mzizi_engine.api.schemas.api.explore.models.data_list_list import DataListList
from mzizi_engine.api.schemas.api.explore.models.data_list_page import DataListPage
from mzizi_engine.api.schemas.api.explore.models.domain_list import DomainList
from mzizi_engine.api.schemas.api.explore.models.table_page import TablePage

__all__ = ["ExploreDatabaseService", "build_explore_database_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class ExploreDatabaseService(ABC):
    """What Database needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def get_data_list_page(
        self, *, domain: str, code: str, limit: int | None, offset: int | None
    ) -> DataListPage:
        """One page of a curated data list."""

    @abstractmethod
    async def get_table_page(
        self,
        *,
        domain: str,
        table: str,
        limit: int | None,
        offset: int | None,
        order: str | None,
        direction: str | None,
        q: str | None,
    ) -> TablePage:
        """One page of a raw table, with search and sorting."""

    @abstractmethod
    async def list_data_lists(self) -> DataListList:
        """The curated data lists, grouped by domain."""

    @abstractmethod
    async def list_database_domains(self) -> DomainList:
        """Every schema with its tables and row counts."""


def build_explore_database_router(service: ExploreDatabaseService, guard: Guard | None = None) -> APIRouter:
    """Routes for Database, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Database"], dependencies=[Depends(guard)] if guard else [])

    @router.get(
        "/v1/explore/db/lists/{domain}/{code}",
        response_model=DataListPage,
        status_code=200,
        summary="One page of a curated data list.",
    )
    async def get_data_list_page(
        domain: Annotated[str, Path(alias="domain")],
        code: Annotated[str, Path(alias="code")],
        limit: Annotated[int | None, Query(alias="limit")] = None,
        offset: Annotated[int | None, Query(alias="offset")] = None,
    ) -> DataListPage:
        return await service.get_data_list_page(domain=domain, code=code, limit=limit, offset=offset)

    @router.get(
        "/v1/explore/db/tables/{domain}/{table}",
        response_model=TablePage,
        status_code=200,
        summary="One page of a raw table, with search and sorting.",
    )
    async def get_table_page(
        domain: Annotated[str, Path(alias="domain")],
        table: Annotated[str, Path(alias="table")],
        limit: Annotated[int | None, Query(alias="limit")] = None,
        offset: Annotated[int | None, Query(alias="offset")] = None,
        order: Annotated[str | None, Query(alias="order")] = None,
        direction: Annotated[str | None, Query(alias="direction")] = None,
        q: Annotated[str | None, Query(alias="q")] = None,
    ) -> TablePage:
        return await service.get_table_page(
            domain=domain, table=table, limit=limit, offset=offset, order=order, direction=direction, q=q
        )

    @router.get(
        "/v1/explore/db/lists",
        response_model=DataListList,
        status_code=200,
        summary="The curated data lists, grouped by domain.",
    )
    async def list_data_lists() -> DataListList:
        return await service.list_data_lists()

    @router.get(
        "/v1/explore/db/domains",
        response_model=DomainList,
        status_code=200,
        summary="Every schema with its tables and row counts.",
    )
    async def list_database_domains() -> DomainList:
        return await service.list_database_domains()

    return router
